/**
 * Genera un cubo gigante de voxels.
 * 
 * @param {number} originX - Coordenada X del centro de la base.
 * @param {number} originY - Coordenada Y de la base inferior.
 * @param {number} originZ - Coordenada Z del centro de la base.
 * @param {Object} [options] - Parámetros de configuración.
 * @param {number} [options.size=20] - Longitud de las aristas del cubo en voxels.
 * @param {boolean} [options.hollow=false] - Si es true, el cubo se genera hueco por dentro.
 * @param {number} [options.wallThickness=1] - Grosor de las paredes si hollow es true.
 * @param {string|number} [options.material='stone'] - Material/bloque a utilizar.
 */
function buildGiantCube(originX, originY, originZ, options = {}) {
    const size = options.size || 20;
    const hollow = options.hollow !== undefined ? options.hollow : false;
    const wallThickness = options.wallThickness || 1;
    const material = options.material || 'stone';

    if (typeof beginBatch === 'function') beginBatch();

    const startTime = performance.now();
    const halfSize = Math.floor(size / 2);
    let blocksCreated = 0;

    // Recorremos los 3 ejes usando índices locales simples de 0 a (size - 1)
    for (let ix = 0; ix < size; ix++) {
        for (let iy = 0; iy < size; iy++) {
            for (let iz = 0; iz < size; iz++) {

                if (hollow) {
                    // Un punto está en la cascara exterior si está a menos distancia que
                    // wallThickness de CUALQUIERA de los 6 extremos (0 o size - 1)
                    const isBorderX = ix < wallThickness || ix >= size - wallThickness;
                    const isBorderY = iy < wallThickness || iy >= size - wallThickness;
                    const isBorderZ = iz < wallThickness || iz >= size - wallThickness;

                    // Si no toca ninguno de los 6 bordes, es espacio interior: saltar
                    if (!isBorderX && !isBorderY && !isBorderZ) {
                        continue;
                    }
                }

                // Mapeo a las coordenadas globales del mundo (centrado en X/Z, base en Y)
                const targetX = originX + (ix - halfSize);
                const targetY = originY + iy;
                const targetZ = originZ + (iz - halfSize);

                setVoxel(targetX, targetY, targetZ, material);
                blocksCreated++;
            }
        }
    }

    if (typeof endBatch === 'function') endBatch();

    const endTime = performance.now();
    console.log(`🧊 Cubo generado (${size}x${size}x${size}). Total voxels: ${blocksCreated}. Tiempo: ${(endTime - startTime).toFixed(2)}ms`);
}

